function sort(text, desc, ignoreCase, skipEmpty, unique){
  var lines = String(text).split(/\r?\n/);
  if(skipEmpty) lines = lines.filter(function(l){return l.trim()!=='';});
  var cmp = ignoreCase
    ? function(a,b){ return a.toLowerCase()<b.toLowerCase()?-1:(a.toLowerCase()>b.toLowerCase()?1:0); }
    : function(a,b){ return a<b?-1:(a>b?1:0); };
  lines.sort(cmp);
  if(desc) lines.reverse();
  if(unique){ var seen={},out=[]; for(var i=0;i<lines.length;i++){ var k=ignoreCase?lines[i].toLowerCase():lines[i]; if(!seen[k]){seen[k]=1;out.push(lines[i]);} } lines=out; }
  return lines.join('\n');
}
var EXPORTS={sort:sort};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SortLinesForgePure = EXPORTS; }
